Change Sheet Properties.code:
// Freeze the header row, move the tab to first position and make sure it's visible.
// The googlesheets adaptor has no helper for spreadsheet-level batchUpdate,
// so call POST /v4/spreadsheets/{spreadsheetId}:batchUpdate with the credential's token.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.access_token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        requests: [
          {
            updateSheetProperties: {
              properties: {
                // Numeric sheet id (the `gid` in the sheet URL), not the tab name.
                sheetId: state.data.sheetId,
                index: 0,
                hidden: false,
                gridProperties: { frozenRowCount: 1, frozenColumnCount: 0 },
              },
              // Only the listed fields are changed.
              fields: 'index,hidden,gridProperties.frozenRowCount,gridProperties.frozenColumnCount',
            },
          },
        ],
      }),
    }
  );
  if (!res.ok) throw new Error(`Sheets API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

