// 1) Insert an empty row directly below the header (row 2).
// No adaptor helper for inserting rows, so call the batchUpdate endpoint directly.
// state.data is left untouched so step 2 can still read the incoming payload.
fn(async state => {
  const spreadsheetId = '1O-a4_RgPF_p8W3I6b5M9wobA3-CBW8hLClZfUik5sos';
  const res = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}:batchUpdate`,
